请对以下 case 进行三维加权评分。

=== case_id ===
Case-22-express-015

=== 用户原始指令 (query.txt) ===
做一个浅色底的物流卡吧,我老是忘看天气结果取快递被淋湿,烦死了。左边一个快递车文字图标做大主视觉,旁边显示"今日新增 6 单"动态数字,右上角放个跳天气app的入口,卡片里直接读未来几小时天气数据,下面是能滚动的列表展示各包裹送达时间,已签收的标绿色对勾完成态,不要渐变。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "做一个浅色底的物流卡吧,我老是忘看天气结果取快递被淋湿,烦死了。左边一个快递车文字图标做大主视觉,旁边显示\"今日新增 6 单\"动态数字,右上角放个跳天气app的入口,卡片里直接读未来几小时天气数据,下面是能滚动的列表展示各包裹送达时间,已签收的标绿色对勾完成态,不要渐变。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "22°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "小雨"
          }
        },
        "nextHours": {
          "summary": {
            "type": "string",
            "description": "未来几小时天气提示，用于提醒取快递前查看降雨情况。",
            "sampleValue": "未来3小时有雨"
          }
        }
      },
      "express": {
        "todayNewText": {
          "type": "string",
          "description": "今日新增快递单量展示文本。",
          "sampleValue": "6 单"
        },
        "parcels": [
          {
            "title": {
              "type": "string",
              "description": "第一件包裹的简短名称。",
              "sampleValue": "生鲜包裹"
            },
            "etaText": {
              "type": "string",
              "description": "第一件包裹预计送达或签收时间。",
              "sampleValue": "12:30 到达"
            },
            "statusText": {
              "type": "string",
              "description": "第一件包裹状态展示文本。",
              "sampleValue": "已签收"
            },
            "statusMark": {
              "type": "string",
              "description": "第一件包裹完成态标记。",
              "sampleValue": "√"
            },
            "statusColor": {
              "type": "string",
              "description": "第一件包裹状态文本颜色。",
              "sampleValue": "#ff64bb5c"
            }
          },
          {
            "title": {
              "type": "string",
              "description": "第二件包裹的简短名称。",
              "sampleValue": "文件快递"
            },
            "etaText": {
              "type": "string",
              "description": "第二件包裹预计送达或签收时间。",
              "sampleValue": "16:10 送达"
            },
            "statusText": {
              "type": "string",
              "description": "第二件包裹状态展示文本。",
              "sampleValue": "派送中"
            },
            "statusMark": {
              "type": "string",
              "description": "第二件包裹完成态标记。",
              "sampleValue": ""
            },
            "statusColor": {
              "type": "string",
              "description": "第二件包裹状态文本颜色。",
              "sampleValue": "#99000000"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/courier_box.png",
      "description": "快递箱子彩色图标，适合用于物流信息、包裹识别和取件提醒主视觉。"
    }
  ]
}

